/* Paraphrased practice questions based exclusively on the bundled course. */
window.QUIZ=[
 {id:'d1-1',topic:'d1',question:'Welke benadering past bij systeemdenken in de verkeerscasus?',options:['Luchtvervuiling, gezondheid en economische kosten in samenhang onderzoeken.','Alleen de luchtkwaliteit beoordelen.','Alleen de economische kosten beoordelen.','De drie dimensies afzonderlijk behandelen zonder hun relaties.'],correct:0,explanation:'Systeemdenken onderzoekt relaties, patronen en terugkoppelingen. In de verkeerscasus hangen luchtvervuiling, gezondheid en economische kosten samen.'},
 {id:'d1-2',topic:'d1',question:'Welke rol heeft de ecologische dimensie volgens de les?',options:['Zij vormt het fundament voor sociale en economische ontwikkeling.','Zij is alleen relevant als de winst verandert.','Zij staat los van de sociale dimensie.','Zij maakt onderzoek naar economische effecten overbodig.'],correct:0,explanation:'De ecologische dimensie vormt volgens de les het fundament voor sociale en economische ontwikkeling; de dimensies beïnvloeden elkaar.'},
 {id:'d2-1',topic:'d2',question:'Wat beschrijven planetaire grenzen?',options:['Een veilige ruimte voor menselijke activiteit binnen ecologische begrenzing.','Een garantie dat ecosystemen elke ingreep kunnen opvangen.','Alleen de financiële grenzen van een bedrijf.','Afzonderlijke problemen zonder onderlinge invloed.'],correct:0,explanation:'Planetaire grenzen beschrijven een veilige operationele ruimte. Overschrijding bedreigt stabiliteit en veerkracht.'},
 {id:'d2-2',topic:'d2',question:'Welke conclusie past bij de Nederlandse stikstofcasus?',options:['Landbouw, ecosystemen en beleidskeuzes beïnvloeden elkaar.','De gevolgen blijven beperkt tot de landbouw.','Ecosysteemschade staat los van voedsel en water.','Beleidskeuzes hebben geen relatie met ecologische effecten.'],correct:0,explanation:'De stikstofcrisis verbindt landbouw, ecosystemen en beleidskeuzes. Schade aan ecosystemen kan doorwerken naar voedsel- en waterbeschikbaarheid.'},
 {id:'d3-1',topic:'d3',question:'Waarom krijgt langer productgebruik aandacht in de R-ladder?',options:['Afvalpreventie en langer gebruik behouden meer waarde dan alleen materiaalrecycling.','Recycling maakt iedere andere circulaire strategie overbodig.','De R-ladder beoordeelt uitsluitend financieel rendement.','Een recyclingclaim bewijst altijd maximale circulariteit.'],correct:0,explanation:'De R-ladder ordent strategieën naar waardebehoud. Afval voorkomen en producten langer gebruiken behouden meer waarde dan alleen materialen recyclen.'},
 {id:'d3-2',topic:'d3',question:'Welke beschrijving hoort bij MUD Jeans in de stof?',options:['Lease A Jeans, met terugname en materiaalhergebruik.','Oude kleding verwerken tot nieuwe truien als Loop.a life.','Passieve ventilatie afleiden van termietenheuvels.','Regionale hubs afwegen voor Roetz.'],correct:0,explanation:'MUD Jeans gebruikt Lease A Jeans met terugname en materiaalhergebruik. Loop.a life is de andere textielcase en verwerkt oude kleding tot nieuwe truien.'},
 {id:'d4-1',topic:'d4',question:'Welke keten beschrijft de albedo-terugkoppeling?',options:['Minder ijs → minder terugkaatsing → verdere opwarming.','Minder ijs → meer terugkaatsing → minder opwarming.','Meer opwarming → meer ijs → minder terugkaatsing.','Minder ijs → geen verandering in warmteopname.'],correct:0,explanation:'Minder ijs betekent minder reflectie en meer opname van warmte. Dat versterkt verdere opwarming.'},
 {id:'d4-2',topic:'d4',question:'Welke aanpak past bij netcongestie als systeemprobleem?',options:['Netuitbreiding, opslag, flexibiliteit en afstemming samen bekijken.','Alleen extra zonnepanelen plaatsen.','Alleen de vraag naar elektriciteit bekijken zonder opwek.','Netcapaciteit los zien van elektrificatie.'],correct:0,explanation:'Netcongestie ontstaat wanneer het net opwek en elektrificatie niet kan volgen. Netuitbreiding, opslag, flexibiliteit en afstemming moeten in samenhang worden bekeken.'},
 {id:'d5-1',topic:'d5',question:'Wat is de inside-out-richting van dubbele materialiteit?',options:['De impact van de organisatie op mens en milieu.','De invloed van duurzaamheidskwesties op de organisatie.','Uitsluitend de winst voor aandeelhouders.','Alleen de marktwaarde van geproduceerd kapitaal.'],correct:0,explanation:'Inside-out gaat over de impact van een organisatie op de wereld. Outside-in gaat over de invloed van duurzaamheidskwesties op de organisatie.'},
 {id:'d5-2',topic:'d5',question:'Welke conclusie past bij meervoudige waardecreatie?',options:['Financieel rendement beschrijft niet alle vormen van waarde.','Groei van financieel kapitaal bewijst dat alle kapitalen groeien.','Menselijk en natuurlijk kapitaal zijn hetzelfde.','Effecten op de omgeving tellen alleen als ze winst opleveren.'],correct:0,explanation:'Het IIRC-kader onderscheidt financieel, geproduceerd, intellectueel, menselijk, sociaal en natuurlijk kapitaal. Daardoor is alleen financieel rendement een te beperkte meetlat.'},
 {id:'d6-1',topic:'d6',question:'Wanneer past een ontwerp bij biomimicry?',options:['Als het leert van de werking van natuurlijke strategieën, processen of systemen.','Zodra het een natuurlijke grondstof bevat.','Zodra het op een natuurlijke vorm lijkt, ongeacht de werking.','Als het uitsluitend de financiële kosten verlaagt.'],correct:0,explanation:'Biomimicry leert van de werking van natuurlijke strategieën, processen en systemen. Alleen een natuurlijke vorm of grondstof gebruiken is onvoldoende.'},
 {id:'d6-2',topic:'d6',question:'Wat voegt regeneratief ontwerp toe volgens de Natural Pavilion-case?',options:['Herstel en positieve impact, zoals versterking van biodiversiteit.','Alleen minder financiële kosten.','De garantie dat natuurlijke materialen elk effect oplossen.','Het loslaten van herbruikbaarheid.'],correct:0,explanation:'Het Natural Pavilion illustreert regeneratief ontwerp met herbruikbare biobased materialen en versterking van biodiversiteit. Het gaat verder dan alleen minder schade.'},
 {id:'d7-1',topic:'d7',question:'Welke uitspraak past bij een wicked problem?',options:['Een interventie kan het vraagstuk veranderen; oplossingen worden in hun context beoordeeld.','Er bestaat altijd één definitieve oplossing.','Betere techniek maakt alle belangenverschillen irrelevant.','De probleemdefinitie blijft altijd ongewijzigd.'],correct:0,explanation:'Wicked problems hebben geen definitieve formulering of eenduidige oplossing. Interventies veranderen het vraagstuk; oplossingen zijn beter of slechter in hun context.'},
 {id:'d7-2',topic:'d7',question:'Waarvoor gebruik je een causal loop diagram?',options:['Om relaties en versterkende of dempende terugkoppelingen zichtbaar te maken.','Om alle relaties tussen variabelen weg te laten.','Om een technische oplossing zonder gevolgen te garanderen.','Om alleen een losse prijs te noteren.'],correct:0,explanation:'Een CLD maakt relaties en terugkoppelingen zichtbaar. In de plasticrecyclingmarkt beïnvloeden prijs, vraag, schaal en kosten elkaar.'},
 {id:'d8-1',topic:'d8',question:'Welke spanning noemt de Roetz-case bij franchising?',options:['Groei kan samengaan met minder grip op materiaalstromen en circulaire normen.','Groei garandeert volledige controle op materiaalstromen.','Franchising maakt sociale effecten irrelevant.','Circulaire normen veranderen nooit door groeikeuzes.'],correct:0,explanation:'Franchising kan Roetz laten groeien, maar vermindert de grip op materiaalstromen en circulaire normen. De keuze vraagt een afweging van meerdere doelen.'},
 {id:'d8-2',topic:'d8',question:'Welke combinatie bieden regionale hubs in de Roetz-case?',options:['Schaalbaarheid met sociale werkgelegenheid.','Alleen internationale massaproductie.','Groei zonder aandacht voor stakeholders.','Het vervangen van alle sociale doelen door financieel rendement.'],correct:0,explanation:'Regionale hubs combineren in de les schaalbaarheid met sociale werkgelegenheid. Internationale massaproductie kan die werkgelegenheid onder druk zetten.'},
 {id:'d9-1',topic:'d9',question:'Hoe beoordeel je issues in een mini-dubbele materialiteitsanalyse?',options:['Beoordeel inside-out-impact en outside-in-risico afzonderlijk en verbind de uitkomst aan een actie.','Beoordeel alleen financieel rendement.','Sla de impactanalyse over zodra een model circulair is.','Bepaal eerst de actie en negeer de relevante issues.'],correct:0,explanation:'De oefening vraagt een case en relevante duurzaamheidsissues, beoordeling van impact en risico, een materialiteitsmatrix en reflectie op een professionele actie.'},
 {id:'d9-2',topic:'d9',question:'Waarom combineer je systeemdenken met LCA?',options:['Systeemdenken onderzoekt relaties; LCA onderzoekt effecten over de levenscyclus.','Beide beperken de analyse tot één productiefase.','LCA maakt onderzoek naar systeemrelaties overbodig.','Een circulaire claim vervangt beide analyses.'],correct:0,explanation:'Systeemdenken onderzoekt relaties en systeemgrenzen. LCA helpt effecten door de levenscyclus te beoordelen; samen voorkom je een te smalle beoordeling.'},
 {id:'e1-1',topic:'e1',question:'Waarom is gas verdelen tijdens de gascrisis een morele keuze?',options:['Er wordt gekozen wie toegang en bescherming krijgt en wie de gevolgen draagt.','Een verdelingskeuze bevat nooit waarden.','Schaarste maakt morele afwegingen overbodig.','Alleen de techniek bepaalt wie beschermd wordt.'],correct:0,explanation:'Economische systemen organiseren toegang, bescherming en verdeling. De gascrisis vroeg wie niet zonder gas mocht komen te zitten.'},
 {id:'e1-2',topic:'e1',question:'Wat onderscheidt externaliteiten van commons?',options:['Externaliteiten zijn afgewentelde kosten; commons zijn gedeelde hulpbronnen.','Externaliteiten zijn gedeelde hulpbronnen; commons zijn afgewentelde kosten.','Beide begrippen betekenen uitsluitend winst.','Commons vragen geen gezamenlijke afspraken.'],correct:0,explanation:'Commons zijn gedeelde hulpbronnen die gezamenlijke afspraken vragen. Externaliteiten zijn kosten die bij anderen dan de veroorzaker terechtkomen.'},
 {id:'e2-1',topic:'e2',question:'Wat verandert bij morele ontkoppeling?',options:['De interpretatie van schadelijk gedrag, zodat iemand zichzelf moreel kan blijven zien.','Schadelijk gedrag wordt vanzelf onschadelijk.','Elke vorm van individuele verantwoordelijkheid verdwijnt.','Groepsnormen hebben geen invloed meer.'],correct:0,explanation:'Morele ontkoppeling rationaliseert schadelijk gedrag. Het verhaal of de interpretatie verandert; dat maakt de schade niet ongedaan.'},
 {id:'e2-2',topic:'e2',question:'Wat kan morele moed in een zwijgcultuur betekenen?',options:['Een moeilijke vraag stellen of een keuze vertragen.','Aannemen dat iedereen instemt omdat niemand spreekt.','Elke bestaande norm zonder vraag volgen.','Systeemdruk gebruiken als bewijs dat niemand kan handelen.'],correct:0,explanation:'Agency is relationeel en beperkt, maar niet afwezig. Morele moed kan bestaan uit vragen stellen, vertragen of schadelijke normalisering doorbreken.'},
 {id:'e3-1',topic:'e3',question:'Wat laat de ASML-case zien over waardecreatie?',options:['Waarde ontstaat uit bijdragen van werknemers, leveranciers, overheid en regio, en aandeelhouders.','Alleen aandeelhouders brengen een relevante bijdrage in.','Specialistische kennis speelt geen rol.','Leveranciers dragen nooit risico.'],correct:0,explanation:'ASML bundelt specialistische kennis, leveranciersinvesteringen, infrastructuur en onderwijs, en aandeelhouderskapitaal. Een onderneming is een wederzijds afhankelijk samenwerkingsverband.'},
 {id:'e3-2',topic:'e3',question:'Wanneer wordt schaal een machtsvraag volgens de module?',options:['Als een bedrijf via lobby, standaarden of data de spelregels kan beïnvloeden.','Zodra alle stakeholders evenveel zeggenschap hebben.','Alleen als er geen financiële prikkels zijn.','Als bedrijfskeuzes geen gevolgen voor anderen hebben.'],correct:0,explanation:'Schaal wordt een machtsvraag wanneer een onderneming de spelregels kan beïnvloeden, bijvoorbeeld via lobby, standaarden of data.'},
 {id:'e4-1',topic:'e4',question:'Welke spanning illustreert de automatische deur?',options:['Meer toegankelijkheid én afhankelijkheid van stroom, sensoren en onderhoud.','Meer toegankelijkheid zonder enige afhankelijkheid.','Alleen verantwoordelijkheid van de gebruiker.','Technologie die geen gedrag beïnvloedt.'],correct:0,explanation:'De automatische deur vergroot toegankelijkheid, maar schept afhankelijkheid van stroom, sensoren en onderhoud. Technologie structureert gedrag.'},
 {id:'e4-2',topic:'e4',question:'Op welke niveaus kun je ingrijpen in de gevolgen van technologie?',options:['Ontwerp, governance en publieke regelgeving.','Alleen individueel gebruik.','Alleen ontwerp, zonder organisatie of regels.','Geen enkel niveau, omdat technologie neutraal is.'],correct:0,explanation:'De module noemt ontwerp, governance en publieke regelgeving als interventieniveaus. Verantwoordelijkheid ligt daardoor niet uitsluitend bij de gebruiker.'},
 {id:'e5-1',topic:'e5',question:'Wat is het probleem van een claim over het hele bedrijf op basis van de Conscious Collection?',options:['Een initiatief kan worden uitgelicht terwijl snelle productiecycli en grote volumes blijven bestaan.','Een initiatief bewijst altijd dat het hele model duurzaam is.','Een claim over een collectie bevat altijd volledige informatie over het bedrijf.','Communicatie en prestaties kunnen nooit uiteenlopen.'],correct:0,explanation:'De Conscious Collection kan een duurzaam initiatief belichten terwijl het volumemodel intact blijft. Een claim over het geheel vraagt meer informatie.'},
 {id:'e5-2',topic:'e5',question:'Wat betekent path dependency voor de beoordeling van greenwashing?',options:['Het kan de spanning verklaren, maar neemt verantwoordelijkheid voor transparantie niet weg.','Het maakt iedere duurzaamheidsclaim ethisch aanvaardbaar.','Het bewijst dat communicatie altijd prestaties weerspiegelt.','Het maakt controleerbaarheid overbodig.'],correct:0,explanation:'Padafhankelijkheid kan verklaren waarom communicatie sneller verandert dan de praktijk. Een verklaring is geen excuus: transparantie en controleerbaarheid blijven verantwoordelijkheden.'}
];
